(function () { const board = document.querySelector('[data-comm-board]'); if (!board) return; const form = board.querySelector('form.comm-filter-card'); const monthInput = form?.querySelector('[data-comm-board-month]'); const yearInput = form?.querySelector('[data-comm-board-year]'); const calendarPicker = board.querySelector('[data-comm-calendar-picker]'); const filterPicker = board.querySelector('[data-comm-board-filter-picker]'); const title = board.querySelector('[data-comm-calendar-title]'); const selectedYear = Number.parseInt(board.dataset.selectedYear || '', 10) || new Date().getFullYear(); const selectedMonth = Number.parseInt(board.dataset.selectedMonth || '', 10) || (new Date().getMonth() + 1); let currentDate = new Date(selectedYear, selectedMonth - 1, 1); function localizedMonthTitle(date) { return date.toLocaleDateString('ar-JO', { month: 'long', year: 'numeric' }); } function setMonthAndSubmit(date) { if (!form || !monthInput || !yearInput) return; monthInput.value = String(date.getMonth() + 1); yearInput.value = String(date.getFullYear()); form.submit(); } function buildPickerConfig(onChange) { const monthSelectPluginFactory = window.monthSelectPlugin || window.flatpickr?.monthSelectPlugin; const config = { dateFormat: 'Y-m', altInput: true, altFormat: 'F Y', altInputClass: 'form-control form-control-sm calendar-month-input', defaultDate: currentDate, disableMobile: true, onChange(selectedDates) { const selectedDate = selectedDates?.[0]; if (!selectedDate) return; onChange(new Date(selectedDate.getFullYear(), selectedDate.getMonth(), 1)); }, }; if (typeof monthSelectPluginFactory === 'function') { config.plugins = [monthSelectPluginFactory({ shorthand: false, dateFormat: 'Y-m', altFormat: 'F Y', theme: 'light', })]; } return config; } board.querySelectorAll('[data-comm-calendar-nav]').forEach((button) => { button.addEventListener('click', () => { const delta = button.dataset.commCalendarNav === 'next' ? 1 : -1; currentDate = new Date(currentDate.getFullYear(), currentDate.getMonth() + delta, 1); if (title) title.textContent = localizedMonthTitle(currentDate); setMonthAndSubmit(currentDate); }); }); if (typeof window.flatpickr === 'function') { if (calendarPicker) window.flatpickr(calendarPicker, buildPickerConfig(setMonthAndSubmit)); if (filterPicker) window.flatpickr(filterPicker, buildPickerConfig(setMonthAndSubmit)); } })();